#!/usr/bin/env python3
class Person:
    def __init__(self, n, a):
        self.name = n
        self.age = a

    def describe(self):
        print("Name:", self.name)
        print("Age:", self.age)

    def __lt__(self, other):
        return self.age < other.age

    def __str__(self):
        return f"My name is {self.name}. I am {self.age."

macron = Person("Emmanuel Macron", 43)
macron.describe()
print(macron)

biden = Person("Joe Biden", 78)
print(f"Macron is younger: {macron < biden}")

class President(Person):
    def set_term(self, term):
        print(f"Setting term to {term}")
        self.term = term

class Employee:
    def work(self):
        print("I should be paid...")

• Getter / Setter
class Employee:
    def __init__(self):
        self.__salary = 0

    def _get_salary(self):
        return self.__salary

    def set_salary(self, salary):
        self.__salary = salary

    def work(self):
        if self.__salary == 0:
            print("I should be paid...")
        else:
            print("I am well paid!")
